p = 61

# Step 1: Calculate N_S(x) = number of solutions to a^2 + b^2 = x mod p
N_S = {}
for x in range(p):
    count = 0
    for a in range(p):
        a2 = (a * a) % p
        for b in range(p):
            b2 = (b * b) % p
            if (a2 + b2) % p == x:
                count += 1
    N_S[x] = count

print("N_S counts calculated.")

# Step 2: Calculate N_D(x) = number of solutions to d^3 - c^3 = x mod p
N_D = {}
for x in range(p):
    count = 0
    for c in range(p):
        c3 = (c * c * c) % p
        for d in range(p):
            d3 = (d * d * d) % p
            if (d3 - c3) % p == x:
                count += 1
    N_D[x] = count

print("N_D counts calculated.")

# Step 3: Calculate N = sum(N_S(x) * N_D(x))
N = 0
for x in range(p):
    N += N_S[x] * N_D[x]

print(f"Total number of solutions N: {N}")
